window.viewProject=projectPage;window.icvV2Back=()=>{const detail=document.getElementById('page-project-detail');const list=document.getElementById('page-projects');if(detail)detail.classList.add('hidden');document.querySelectorAll('[id^="page-"]').forEach(x=>{if(x.id!=='page-projects')x.classList.add('hidden')});if(list)list.classList.remove('hidden');document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));const b=document.querySelector('.nav button[data-page="projects"]');if(b)b.classList.add('active');if(window.pageTitle)pageTitle.textContent='المشاريع';if(window.icvStructure?.renderProjects)window.icvStructure.renderProjects();window.scrollTo({top:0,behavior:'smooth'});};
